if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/sw.js').catch(()=>{});let installPrompt;addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;const b=document.querySelector('#install');if(b)b.disabled=false});document.querySelector('#install')?.addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else document.querySelector('#install-note').textContent='Use your browser menu: Install app or Add to Home Screen. On iPhone/iPad, use Safari → Share → Add to Home Screen.'});
